oice":false,"counts_as_training_talent":false,"display_name":"Resonant Note","effect":null,"factory_combat_bucket":null,"factory_routing":null,"full_description":null,"owner_removable":false,"packet_type":"source_verified_base_ability_packet","range":null,"runtime_component_id":"TAL_SOUND_RESONANT_NOTE","scaling":null,"source_reference":{"source_anchor":"record:TAL_SOUND_RESONANT_NOTE","source_authority_sha256":"4daf167cf634f27efef4dd2f1c8700bb4b7037cc6234c32be1af90aea5916385","source_file_sha256":"59fb3a6b378f6bc9753e4ec630e4535576ecace024a20ba9ae001264df2540e4","source_pack":"Tianxia_Factory_HF05ZVK_R1H_Phase2I_HF2","source_path":"09_RULES/Indexes/Canonical_Talent_Catalog.json","source_version":"HF05ZVK-R1H Phase 2I HF2 / Canon Corpus P2A"},"source_refs":["Tianxia_Sphere_Compendium_Player_Facing_Compilation_HF05L_HF05G_EDITORIAL_CLEANUP_2026_06_26(1).md :: Sphere of Sound :: Base Sphere Abilities > Resonant Note"],"tags":null,"target":null,"trigger":null,"use_limit":null},{"action_type":null,"automatic_grant":true,"base_ability_id":"TAL_SOUND_SOUND_INITIATION","candidate_record_id":"TAL_SOUND_SOUND_INITIATION","catalog_role":"source_verified_packet_action_row","cost":null,"counts_as_advancement_talent":false,"counts_as_talent_choice":false,"counts_as_training_talent":false,"display_name":"Sound Initiation","effect":"When you first learn Sound, choose one expression as your primary method:
voice;
bell;
drum;
zither or stringed instrument;
flute or reed;
whistle;
clap or footfall;
mantra or scripture chant;
bone resonance;
another GM-approved sound practice.
This choice is descriptive unless a variant or feature says otherwise.
You learn to create minor cultivated sound within 60 feet. As an Action, you may create one harmless sound no louder than a shout, throw your voice to a visible point, dampen one small noise, cause one unattended object to hum, or cause a small surface to vibrate.
These minor sounds cannot deal damage, impose conditions, replace a check, transmit complex messages through barriers, or imitate a specific creature well enough to deceive without a check.","factory_combat_bucket":null,"factory_routing":null,"full_description":"#### Sound Initiation
When you first learn Sound, choose one expression as your primary method:
voice;
bell;
drum;
zither or stringed instrument;
flute or reed;
whistle;
clap or footfall;
mantra or scripture chant;
bone resonance;
another GM-approved sound practice.
This choice is descriptive unless a variant or feature says otherwise.
You learn to create minor cultivated sound within 60 feet. As an Action, you may create one harmless sound no louder than a shout, throw your voice to a visible point, dampen one small noise, cause one unattended object to hum, or cause a small surface to vibrate.
These minor sounds cannot deal damage, impose conditions, replace a check, transmit complex messages through barriers, or imitate a specific creature well enough to deceive without a check.","owner_removable":false,"packet_type":"source_verified_variant_scripture_packet","range":null,"runtime_component_id":"TAL_SOUND_SOUND_INITIATION","scaling":[],"source_reference":{"source_anchor":"line:78628:column:1","source_authority_sha256":"4daf167cf634f27efef4dd2f1c8700bb4b7037cc6234c32be1af90aea5916385","source_column":1,"source_context_sha256":"b179c2ce0740e1e6703d2f7dd0e98e302a487742f47c15dd1d2a970f6e500725","source_file_sha256":"67f67275889467d43605debaa0c05dc5ddde9ba079222819aabea27c66167775","source_line":78628,"source_pack":"Tianxia_Factory_HF05ZVK_R1H_Phase2I_HF2","source_path":"09_RULES/Source_Text/Tianxia_Sphere_Compendium_Latest_R0I_85Spheres.md","source_section":"Sphere of Sound > Base Abilities > Sound Initiation","source_version":"HF05ZVK-R1H Phase 2I HF2 / Canon Corpus P2A"},"source_refs":["Tianxia_Sphere_Compendium_Player_Facing_Compilation_HF05L_HF05G_EDITORIAL_CLEANUP_2026_06_26(1).md :: Sphere of Sound :: Base Sphere Abilities > Sound Initiation"],"tags":["automatic_sphere_component","source_verified_variant_scripture_packet"],"target":null,"trigger":null,"use_limit":null}]

